package com.smarttask.service;
import com.smarttask.dto.ApiDtos.*;import com.smarttask.entity.*;import com.smarttask.repository.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class FocusService {private final FocusSessionRepository sessions;private final UserRepository users;private final TaskRepository tasks;public FocusService(FocusSessionRepository s,UserRepository u,TaskRepository t){sessions=s;users=u;tasks=t;}public FocusView save(Long uid,FocusRequest r){if(r.endedAt().isBefore(r.startedAt())||Duration.between(r.startedAt(),r.endedAt()).toMinutes()>r.durationMinutes()+5)throw new IllegalArgumentException("Session timestamps are invalid.");var u=users.findById(uid).orElseThrow();Task task=r.taskId()==null?null:tasks.findByIdAndUserId(r.taskId(),uid).orElseThrow(()->new NoSuchElementException("Task not found."));var s=sessions.save(new FocusSession(u,task,r.durationMinutes(),r.startedAt(),r.endedAt()));return new FocusView(s.getId(),s.getDurationMinutes(),s.getStartedAt(),s.getEndedAt());}public List<FocusView> list(Long uid){return sessions.findByUserIdAndStartedAtAfterOrderByStartedAtAsc(uid,Instant.now().minus(Duration.ofDays(30))).stream().map(s->new FocusView(s.getId(),s.getDurationMinutes(),s.getStartedAt(),s.getEndedAt())).toList();}}
